payload.file_after:
.painel-lotado .fechamento{font-family:'Caveat',cursive;font-weight:700;font-size:22px;line-height:1.25;
  color:var(--azul-escuro);margin-top:15px;transform:rotate(-.5deg)}

/* lista de espera */
.espera-topo{display:flex;align-items:center;gap:clamp(14px,3vw,22px);flex-wrap:wrap}
.ampulheta{width:clamp(46px,9vw,60px);height:auto;flex:none}
.ampulheta .vidro{fill:none;stroke:var(--azul-marca);stroke-width:3;stroke-linecap:round}
.ampulheta .areia{fill:var(--laranja)}
.ampulheta .grao{stroke:var(--laranja);stroke-width:3;stroke-linecap:round;animation:cair 1.6s linear infinite}
@keyframes cair{0%{opacity:0;transform:translateY(-3px)}18%,78%{opacity:1}100%{opacity:0;transform:translateY(8px)}}
.fila{position:relative;margin-top:24px;display:grid;gap:12px;max-width:540px}
/* fio da fila: some atrás das senhas e aparece só nos vãos, como um varal */
.fila::before{content:'';position:absolute;left:35px;top:20px;bottom:20px;width:2px;
  background:repeating-linear-gradient(180deg,var(--papel-borda) 0 5px,transparent 5px 11px)}
.senha{position:relative;display:flex;align-items:center;gap:15px;padding:13px 18px 13px 15px;
  background:#FFFCF6;border:2px solid var(--papel-borda);border-radius:12px;
  box-shadow:0 14px 26px -22px rgba(30,42,58,.9);
  animation:colar .5s cubic-bezier(.2,.9,.3,1.5) both}
.senha .num{position:relative;z-index:1;flex:none;display:flex;align-items:center;justify-content:center;
  width:40px;height:40px;border-radius:50%;background:var(--azul-marca);color:var(--papel);
  font-weight:800;font-size:15px;letter-spacing:-.02em}
.senha .picote{flex:none;align-self:stretch;width:2px;
  background:repeating-linear-gradient(180deg,var(--papel-borda) 0 4px,transparent 4px 9px)}
.senha .quem{flex:1;min-width:0;font-weight:600;font-size:15.5px;line-height:1.25;overflow-wrap:anywhere}
.senha .etiqueta{flex:none;font-weight:700;font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:var(--laranja)}
.senha.proximo{border-color:rgba(232,123,35,.5);
  background:linear-gradient(90deg,rgba(232,123,35,.12),#FFFCF6 62%)}
.senha.proximo .num{background:var(--laranja)}
.senha.voce{border-color:rgba(27,78,155,.55);box-shadow:0 0 0 3px rgba(27,78,155,.12),0 14px 26px -22px rgba(30,42,58,.9)}
.legenda-fila{margin-top:16px;font-size:13px;color:var(--tinta-fraca);font-weight:500;max-width:62ch;line-height:1.6}
